using AssetForge.Core.Models;using AssetForge.Infrastructure.Data;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.AspNetCore.Mvc.Rendering;using Microsoft.EntityFrameworkCore;namespace AssetForge.Web.Pages;public class MaintenanceModel(AssetForgeDbContext db):PageModel{public List<MaintenanceRecord> Records{get;set;}=[];public SelectList Assets{get;set;}=null!;[BindProperty]public MaintenanceRecord Input{get;set;}=new();public async Task OnGetAsync()=>await Load();public async Task<IActionResult> OnPostAsync(){await Phase4Upgrade.ApplyAsync(db);Input.LoggedBy=User.Identity?.Name??"admin";db.MaintenanceRecords.Add(Input);var a=await db.Assets.FindAsync(Input.AssetId);if(a!=null)a.Status="Repair";db.AuditEvents.Add(new AuditEvent{AssetId=Input.AssetId,Action="Repair opened",Details=Input.Issue,PerformedBy=Input.LoggedBy});await db.SaveChangesAsync();return RedirectToPage();}public async Task<IActionResult> OnPostCompleteAsync(long id,string resolution,decimal? cost){await Phase4Upgrade.ApplyAsync(db);var r=await db.MaintenanceRecords.Include(x=>x.Asset).FirstOrDefaultAsync(x=>x.Id==id);if(r!=null){r.Status="Completed";r.CompletedUtc=DateTime.UtcNow;r.Resolution=resolution;r.Cost=cost;if(r.Asset!=null)r.Asset.Status="Available";await db.SaveChangesAsync();}return RedirectToPage();}private async Task Load(){await Phase4Upgrade.ApplyAsync(db);Records=await db.MaintenanceRecords.Include(x=>x.Asset).OrderByDescending(x=>x.OpenedUtc).ToListAsync();Assets=new(await db.Assets.Where(x=>x.Status!="Retired").OrderBy(x=>x.AssetTag).Select(x=>new{x.Id,Name=x.AssetTag+" · "+x.Name}).ToListAsync(),"Id","Name");}}
